// Devuelve el challenge sólo si el verify token coincide. Sin esa
// comprobación, cualquiera que adivine la URL registra su propio webhook.
const q = $input.first().json.query ?? {};
const esperado = $env.WHATSAPP_VERIFY_TOKEN;

if (q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === esperado) {
  return [{ json: {}, pairedItem: 0, binary: {}, noWebhookResponse: false, data: q['hub.challenge'] }];
}

return [{ json: { error: 'verify token no coincide' } }];

// Traduce las acciones que devolvió Postgres a llamadas de la Cloud API.
// Sin lógica de negocio: sólo cambio de formato.
//
// El texto viene en el HTML que arma la base para todos los canales, y
// WhatsApp no entiende HTML: se traduce a su marcado. Es la misma
// conversión que hace worker/src/whatsapp.js, y por la misma razón.
function aWhatsApp(html) {
  return String(html ?? '')
    .replace(/<pre>([\s\S]*?)<\/pre>/g, (_, c) => '```\n' + c.trim() + '\n```')
    .replace(/<code>([\s\S]*?)<\/code>/g, '`$1`')
    .replace(/<b>([\s\S]*?)<\/b>/g, '*$1*')
    .replace(/<i>([\s\S]*?)<\/i>/g, '_$1_')
    .replace(/<[^>]+>/g, '')
    .replaceAll('&lt;', '<')
    .replaceAll('&gt;', '>')
    .replaceAll('&quot;', '"')
    .replaceAll('&amp;', '&');
}

const salida = [];

for (const item of $input.all()) {
  const acciones = item.json.respuesta?.acciones ?? [];

  for (const a of acciones) {
    if (a.tipo !== 'enviar' || !a.para) continue;

    const texto = aWhatsApp(a.texto);

    if (a.botones && a.botones.length > 0) {
      salida.push({ json: { cuerpo: {
        messaging_product: 'whatsapp',
        to: a.para,
        type: 'interactive',
        interactive: {
          type: 'button',
          body: { text: texto.slice(0, 1024) },
          action: { buttons: a.botones.slice(0, 3).map((b) => ({
            type: 'reply',
            reply: { id: String(b.d).slice(0, 256), title: String(b.t).slice(0, 20) },
          })) },
        },
      } } });
    } else {
      salida.push({ json: { cuerpo: {
        messaging_product: 'whatsapp',
        to: a.para,
        type: 'text',
        text: { preview_url: false, body: texto.slice(0, 4096) },
      } } });
    }
  }
}

return salida;
